function HasseDiagram({
  n,
  colorBy = "trait",
  vs = VS_DEFAULT,
  zStar = 0.5,
}: {
  n: number;
  colorBy?: "trait" | "fitness";
  vs?: number;
  zStar?: number;
}) {
  const theme = useHostTheme();

  const layout = useMemo(() => {
    const left = 28;
    const right = 28;
    const top = 18;
    const bottom = n <= 12 ? 56 : 40;
    const plotW = SVG_W - left - right;
    const colGap = plotW / n;

    if (n <= FULL_HASSE_N) {
      const layers: number[][] = Array.from({ length: n + 1 }, () => []);
      const nGen = 1 << n;
      for (let g = 0; g < nGen; g++) layers[popcount(g)].push(g);

      const maxLayer = Math.max(...layers.map((L) => L.length));
      const r =
        n <= 2 ? 16 : n <= 3 ? 13 : n <= 4 ? 9 : n <= 5 ? 6.2 : n <= 6 ? 4.6 : 3.5;
      const spacing =
        n <= 2 ? 52 : n <= 3 ? 42 : n <= 4 ? 28 : n <= 5 ? 18 : n <= 6 ? 13 : 10.2;
      const plotH = Math.max(spacing * maxLayer, 96);
      const height = top + plotH + bottom;

      const pos = new Map<number, { x: number; y: number; k: number }>();
      for (let k = 0; k <= n; k++) {
        const L = layers[k];
        const x = left + k * colGap;
        const m = L.length;
        for (let i = 0; i < m; i++) {
          const y = top + plotH / 2 + (i - (m - 1) / 2) * spacing;
          pos.set(L[i], { x, y, k });
        }
      }

      const edges: { x1: number; y1: number; x2: number; y2: number }[] = [];
      for (let g = 0; g < nGen; g++) {
        const a = pos.get(g);
        if (!a) continue;
        for (let b = 0; b < n; b++) {
          if ((g & (1 << b)) === 0) {
            const h = g | (1 << b);
            const c = pos.get(h);
            if (!c) continue;
            edges.push({ x1: a.x, y1: a.y, x2: c.x, y2: c.y });
          }
        }
      }

      return {
        mode: "nodes" as const,
        layers,
        pos,
        edges,
        r,
        colGap,
        left,
        top,
        plotH,
        height,
        counts: layers.map((L) => L.length),
      };
    }

    const counts = binomialLayerCounts(n);
    const maxC = counts.reduce(
      (m, x) => (Number.isFinite(x) && x > m ? x : m),
      1,
    );
    const maxBar = 210;
    const minBar = n >= 80 ? 4 : 12;
    const plotH = maxBar + 20;
    const height = top + plotH + bottom;
    const gapless = n > 40;
    const barW = gapless ? Math.max(colGap, 0.75) : Math.min(24, colGap * 0.7);
    const bars = counts.map((count, k) => {
      const ratio = Number.isFinite(count) ? Math.min(1, count / maxC) : 1;
      const h = minBar + (maxBar - minBar) * Math.sqrt(ratio);
      const x = left + k * colGap;
      const y = top + plotH / 2 - h / 2;
      return { k, x, y, w: barW, h, count };
    });

    return {
      mode: "layers" as const,
      layers: [] as number[][],
      pos: new Map<number, { x: number; y: number; k: number }>(),
      edges: [] as { x1: number; y1: number; x2: number; y2: number }[],
      r: 0,
      colGap,
      left,
      top,
      plotH,
      height,
      counts,
      bars,
    };
  }, [n]);

  const showLabels = n <= 4;
  const edgeOpacity = n <= 3 ? 0.5 : n <= 4 ? 0.38 : n <= 5 ? 0.22 : n <= 6 ? 0.14 : 0.1;
  const fontSize = n <= 2 ? 9 : n <= 3 ? 7.5 : 6;
  const labelEvery = kLabelStep(n);
  const showK = (k: number) =>
    k === 0 || k === n || k % labelEvery === 0;
  const kTicks: number[] = [];
  for (let k = 0; k <= n; k++) if (showK(k)) kTicks.push(k);

  return (
    <svg
      width="100%"
      viewBox={`0 0 ${SVG_W} ${layout.height}`}
      role="img"
      aria-label={
        colorBy === "fitness"
          ? `Boolean lattice for ${n} loci, colored by stabilizing fitness`
          : `Boolean lattice for ${n} loci, Hamming weight increasing left to right`
      }
    >
      {kTicks.map((k) => {
        const x = layout.left + k * layout.colGap;
        return (
          <g key={`lab-${k}`}>
            {layout.mode === "nodes" ? (
              <line
                x1={x}
                y1={layout.top}
                x2={x}
                y2={layout.top + layout.plotH}
                stroke={theme.stroke.tertiary}
                strokeWidth={0.5}
                opacity={0.35}
              />
            ) : null}
            {showK(k) ? (
              <text
                x={x}
                y={layout.height - (n <= 12 ? 32 : 18)}
                textAnchor="middle"
                fontSize={n <= 12 ? 10 : 8}
                fill={theme.text.secondary}
                fontFamily="inherit"
              >
                {n <= 12 ? `k = ${k}` : k}
              </text>
            ) : null}
            {n <= 12 && showK(k) ? (
              <text
                x={x}
                y={layout.height - 18}
                textAnchor="middle"
                fontSize={10}
                fill={theme.text.secondary}
                fontFamily="inherit"
              >
                z = {k === 0 ? "0" : k === n ? "1" : `${k}/${n}`}
              </text>
            ) : null}
          </g>
        );
      })}

      {layout.mode === "layers" && layout.bars && n <= 40
        ? layout.bars.slice(0, -1).map((bar, i) => {
            const nxt = layout.bars[i + 1];
            return (
              <line
                key={`e-${i}`}
                x1={bar.x}
                y1={bar.y + bar.h / 2}
                x2={nxt.x}
                y2={nxt.y + nxt.h / 2}
                stroke={theme.stroke.primary}
                strokeWidth={1}
                opacity={0.28}
              />
            );
          })
        : layout.mode === "nodes"
          ? layout.edges.map((e, i) => (
              <line
                key={i}
                x1={e.x1}
                y1={e.y1}
                x2={e.x2}
                y2={e.y2}
                stroke={theme.stroke.primary}
                strokeWidth={n <= 4 ? 1.1 : 0.7}
                opacity={edgeOpacity}
              />
            ))
          : null}

      {colorBy === "fitness" ? (
        <line
          x1={layout.left + zStar * n * layout.colGap}
          y1={layout.top}
          x2={layout.left + zStar * n * layout.colGap}
          y2={layout.top + layout.plotH}
          stroke={theme.stroke.primary}
          strokeWidth={1.1}
          strokeDasharray="4 3"
          opacity={0.75}
        />
      ) : null}

      {layout.mode === "layers" && layout.bars
        ? layout.bars.map((bar) => {
            const z = bar.k / n;
            const w = fitnessW(z, vs, zStar);
            const fill = colorBy === "fitness" ? fitnessFill(w) : traitFill(z);
            return (
              <rect
                key={`bar-${bar.k}`}
                x={bar.x - bar.w / 2}
                y={bar.y}
                width={bar.w}
                height={bar.h}
                rx={n > 40 ? 0 : 3}
                fill={fill}
                stroke={n > 40 ? fill : theme.stroke.primary}
                strokeWidth={n > 40 ? 0 : 0.8}
              />
            );
          })
        : Array.from(layout.pos.entries()).map(([g, p]) => {
            const z = p.k / n;
            const w = fitnessW(z, vs, zStar);
            const fill = colorBy === "fitness" ? fitnessFill(w) : traitFill(z);
            const labelFill =
              colorBy === "fitness"
                ? luminance(fill) > 140
                  ? "black"
                  : "white"
                : z > 0.55
                  ? "white"
                  : "black";
            return (
              <g key={g}>
                <circle
                  cx={p.x}
                  cy={p.y}
                  r={layout.r}
                  fill={fill}
                  stroke={theme.stroke.primary}
                  strokeWidth={n <= 4 ? 1.2 : 0.8}
                />
                {showLabels ? (
                  <text
                    x={p.x}
                    y={p.y + fontSize * 0.35}
                    textAnchor="middle"
                    fontSize={fontSize}
                    fontFamily="inherit"
                    fill={labelFill}
                  >
                    {bitstring(g, n)}
                  </text>
                ) : null}
              </g>
            );
          })}

      <text
        x={SVG_W / 2}
        y={layout.height - 4}
        textAnchor="middle"
        fontSize={10}
        fill={theme.text.tertiary}
        fontFamily="inherit"
      >
        Hamming weight k →
      </text>
    </svg>
  );
}

export default function PolygenicMaintenanceEfficiency() {
  const theme = useHostTheme();
  const [nRaw, setN] = useCanvasState("lociN", 4);
  const [vsRaw, setVs] = useCanvasState("stabVs", VS_DEFAULT);
  const [zStarRaw, setZStar] = useCanvasState("zStar", 0.5);
  const [npopRaw, setNpop] = useCanvasState("popN", NPOP_DEFAULT);
  const [alphaRaw, setAlpha] = useCanvasState("dirichletAlpha", ALPHA_DEFAULT);
  const [alpha0Raw, setAlpha0] = useCanvasState("dirichletAlpha0", ALPHA0_DEFAULT);
  const n = clampN(nRaw);
  const vs = clampVs(vsRaw);
  const zStar = clamp01(zStarRaw);
  const npop = clampNpop(npopRaw);
  const alpha = clampAlpha(alphaRaw);
  const alpha0 = clampAlpha0(alpha0Raw);
  const sEq = sFromVs(vs);
  const boltz = useMemo(
    () => boltzmannMaint(n, vs, zStar, npop, Math.log(alpha), 1),
    [n, vs, zStar, npop, alpha],
  );
  const boltz0 = useMemo(
    () =>
      boltzmannMaint(n, vs, zStar, npop, logAlphaFromAlpha0(alpha0, n), 2),
    [n, vs, zStar, npop, alpha0],
  );
  const a0Implied = impliedAlpha0(alpha, n);
  const aImplied = impliedAlpha(alpha0, n);
  const nGen = 2 ** n;
  const mid = binomial(n, Math.floor(n / 2));
  const nEdges = n * 2 ** (n - 1);

  return (
    <Stack gap={24}>
      <Stack gap={8}>
        <H1>More genes, more efficient?</H1>
        <Text tone="secondary">
          Premise: same trait, same selection on the phenotype, more
          genes coding it (the word “same” will need a careful look, and
          a few alternative definitions).
          We want to ask whether polygenicity raises the efficiency with
          which selection maintains evolutionary information at equilibrium.
          Said differently: Is there an advantage, in equilibrium maintenance efficiency, to a
          trait being encoded by more loci rather than fewer — once the
          phenotype and the selective environment are held fixed?
        </Text>
      </Stack>

      <Stack gap={10}>
        <H2>Information maintained by selection</H2>
        <Text>
          Let x = (x_g) over genotypes g be the genotype-frequency vector, and
          let X be a population state on the genotype-frequency simplex. We
          measure the information as the KL divergence between the distribution
          under selection at that state, {"ψ^X"}, and always the neutral
          equilibrium, {"φ^{X^*}"}:
        </Text>
        <TeX
          name="dkl"
          label="D_KL of psi^X given phi^{X-star} equals the integral of psi^X log psi^X over phi^{X-star}"
        />
        <Text>
          The second argument is always the neutral equilibrium. Selection does
          not have to be at equilibrium: X can be any state. It happens that in
          this code we will only evaluate the quantity at selected equilibrium.
          For convenience, when we talk about a trait encoded by n loci we write
        </Text>
        <TeX
          name="Dn"
          label="D(n) equals D_KL of psi_n^{X-star} given phi_n^{X-star}"
        />
      </Stack>

      <Stack gap={10}>
        <H2>What we mean by maintenance efficiency</H2>
        <Text>
          Information maintenance efficiency, as well is information efficiency, measures the information accumulated by natural
          selection relative to the cost of selection, C. The motivation for
          this measure comes from the information-theoretic framework of Hledík,
          Barton, and Tkačik, who showed that the rate of information
          accumulation is formally bounded by a quantity, C, that can be interpreted
          as a cost of selection. Importantly, this bound is derived when
          information is measured over the genotype-frequency state space, which
          provides the most complete description of the population's genetic
          composition within our model. The bound takes the form:
        </Text>
        <TeX
          name="bound"
          label="D_KL of psi to the X(t+1) given phi-star, minus D_KL of psi to the X(t) given phi-star, equals D(X^{t+1}) minus D(X^t) equals Delta D of X^t, at most k N times expected cost at t"
        />
        <Text>
          N stands for population size (N_e actually), and k is the mode of
          reproduction: 1 for haploids, 2 for diploids. C(x) comes forth as an
          upper bound, and because of its meaning this is why they called it a
          cost.
        </Text>
        <Text>
          First we need to clarify what is meant with this term. The cost of
          selection quantifies the evolutionary expenditure associated with
          favoring some genotypes over others. Conceptually, selection
          increases the representation of fitter genotypes, but this comes at a
          cost: individuals with lower fitness either die because of lower
          fitness or simply, in the passage of time, stop being represented as
          the population will be taken over by offspring of the fitter types.
          This also reduces the population's reproductive output relative to a
          hypothetical population in which all individuals had the highest
          fitness. This idea is closely related to Haldane's cost of natural
          selection, originally formulated in terms of the reproductive excess
          required for the substitution of advantageous alleles, and to the
          genetic load, which measures the reduction in mean fitness relative
          to an optimal genotype.
        </Text>
        <H3>Cost C(x)</H3>
        <Text>
          The term cost of selection naturally appears as the KL divergence
          between the genotype distributions after and before selection:
        </Text>
        <TeX
          name="cost"
          label="x-prime_g equals x_g omega(g) over x dot omega. C(x) equals D_KL of x-prime given x equals sum_g x-prime_g log x-prime_g over x_g"
        />
        <Text>
          Here, (x · ω) is the mean fitness of the population. The cost
          measures how strongly selection changes the genotype distribution in
          a single generation. It is zero when selection leaves genotype
          frequencies unchanged and increases as the distributions become more
          distinguishable.
        </Text>
        <Text>
          This naturally employs a natural measure for the efficiency of
          information accumulation, and therefore over a time interval [0, T]
          we can define accumulation efficiency as
        </Text>
        <TeX
          name="eta_T"
          label="eta_T equals D(X^T) minus D(X^0), over k N times the sum of expected costs"
        />
        <Text>
          Selection can increase this divergence, but the rate of this
          information gain is bounded by the cost incurred. Importantly, even
          at evolutionary equilibrium, when information is no longer
          accumulating, selection may continue to incur a cost by
          counteracting mutation and genetic drift. This motivates the notion
          of maintenance efficiency: how much information about the fitness
          landscape can be maintained for a given ongoing cost of selection.
        </Text>
        <TeX
          name="eta_maint_eq"
          label="eta_maint equals D_eq over k N times expected cost at equilibrium"
        />
        <Text tone="secondary" size="small">
          Information sitting at equilibrium per unit of ongoing selective
          cost — not the rate at which new information is accumulated.
        </Text>
      </Stack>

      <Divider />

      <Stack gap={8}>
        <H2>The scaling problem</H2>
        <Text>
          Landscapes for n = 1, 2, 3, … cannot be literally the same object:
          the genotype space grows as 2ⁿ. Pairwise topography (a Σ matrix with
          entries sᵢ, εᵢⱼ) does not tell you how to add a locus without
          changing the biology. What we need is a family ωₙ that represents
          the same trait under the same selection, with only the encoding
          changing.
        </Text>
      </Stack>

      <Table
        headers={["Held fixed as n grows", "Allowed to change"]}
        rows={[
          ["Phenotype range (here [0, 1])", "Number of binary loci n"],
          [
            "Phenotype-to-fitness map W(z)",
            "How genotype g maps to z (the encoding)",
          ],
          [
            "Stabilizing width Vs and optimum z*",
            "Genotype space {0,1}ⁿ and its equilibria",
          ],
          [
            "Biological meaning of the trait",
            "Per-locus effect size (here 1/n)",
          ],
        ]}
      />

      <Divider />

      <Stack gap={10}>
        <H2>Additive polygenic trait</H2>
        <Text>
          A genotype is a binary string g = (g₁, …, gₙ) with each locus gᵢ ∈
          {" {0, 1}"}. These 2ⁿ strings are the vertices of the n-dimensional
          hypercube. Two genotypes are neighbors when they differ at exactly one
          locus (Hamming distance 1). Laying vertices out by Hamming weight k =
          number of 1s gives the Boolean lattice Hasse diagram — a layered
          genotype network.
        </Text>
      </Stack>

      <Card>
        <CardHeader>Encoded within a normalized interval</CardHeader>
        <CardBody>
          <Stack gap={10}>
            <Text>
              Every genotype maps to the same trait interval [0, 1], independent
              of n. The additive encoding is the mean allelic dose:
            </Text>
            <TeX name="zn" label="z_n(g) equals one over n times sum g_i, which is k over n" />
            <Text tone="secondary" size="small">
              All-wild-type 00…0 has z = 0. All-derived 11…1 has z = 1. A
              genotype with Hamming weight k sits at z = k/n. Changing n only
              changes how finely [0, 1] is partitioned, not the interval itself.
            </Text>
            <Text>
              The first fitness map sits on that same interval — Gaussian
              stabilizing selection around a fixed optimum z*, with width Vs
              held fixed as n grows:
            </Text>
            <TeX
              name="omega"
              label="omega_n(g) equals exp of minus (z_n(g) minus z-star) squared over 2 V_s"
            />
            <Text tone="secondary" size="small">
              W_max = 1. Smaller Vs is stronger selection. Equivalent
              parameterization s = 1/(2 Vs). Peak fitness 1 at z = z*. Same W
              for every n; only the encoding zₙ changes.
            </Text>
          </Stack>
        </CardBody>
      </Card>

      <Card>
        <CardHeader
          trailing={
            <Row gap={8} align="center">
              <ColorBar />
            </Row>
          }
        >
          Hamming-weight layered genotype network
        </CardHeader>
        <CardBody>
          <Stack gap={14}>
            <Row gap={12} align="center" wrap>
              <Text weight="medium">loci n</Text>
              <input
                type="range"
                min={0}
                max={SLIDER_STEPS}
                step={1}
                value={nToSlider(n)}
                onChange={(e: { currentTarget: { value: string } }) =>
                  setN(sliderToN(Number(e.currentTarget.value)))
                }
                aria-label="Number of loci"
                style={{
                  width: 260,
                  accentColor: theme.accent.primary,
                  cursor: "pointer",
                }}
              />
              <Text weight="medium">{n}</Text>
              <Row gap={4} align="center" wrap>
                {N_JUMPS.map((v) => (
                  <Pill
                    key={v}
                    size="sm"
                    active={v === n}
                    onClick={() => setN(v)}
                  >
                    {v}
                  </Pill>
                ))}
              </Row>
            </Row>

            <Row gap={8} wrap>
              <Stat value={String(n)} label="loci n" />
              <Stat value={formatPow2(n)} label="genotypes 2ⁿ" />
              <Stat value={formatEdges(n)} label="hypercube edges" />
              <Stat value={formatCount(mid)} label="widest layer C(n, ⌊n/2⌋)" />
            </Row>

            <div
              style={{
                border: `1px solid ${theme.stroke.tertiary}`,
                background: theme.bg.editor,
                padding: "8px 4px 4px",
              }}
            >
              <HasseDiagram n={n} colorBy="trait" />
            </div>

            <Text tone="secondary" size="small">
              {n <= FULL_HASSE_N
                ? "Each circle is a genotype. Layers are Hamming weight k = 0 (left, white, z = 0) through k = n (right, black, z = 1). Edges are single-locus flips. Bitstrings labeled only for n ≤ 4."
                : `At n = ${n} there are ${formatCount(nGen)} genotypes — too many to draw. Each bar is one Hamming-weight layer (C(n,k) genotypes, all with the same z = k/n). Bar height scales as √C(n,k). The full node picture stops at n = ${FULL_HASSE_N}.`}
            </Text>
          </Stack>
        </CardBody>
      </Card>

      <Card>
        <CardHeader
          trailing={
            <Row gap={8} align="center">
              <FitnessColorBar />
            </Row>
          }
        >
          Fitness on the same lattice
        </CardHeader>
        <CardBody>
          <Stack gap={14}>
            <Row gap={12} align="center" wrap>
              <Text weight="medium">optimum z*</Text>
              <input
                type="range"
                min={0}
                max={1}
                step={0.05}
                value={zStar}
                onChange={(e: { currentTarget: { value: string } }) =>
                  setZStar(Number(e.currentTarget.value))
                }
                aria-label="Fitness optimum z star"
                style={{
                  width: 220,
                  accentColor: theme.accent.primary,
                  cursor: "pointer",
                }}
              />
              <Text tone="secondary" size="small">
                {zStar.toFixed(2)}
              </Text>
            </Row>
            <Row gap={12} align="center" wrap>
              <Text weight="medium">width Vs</Text>
              <input
                type="range"
                min={0}
                max={VS_SLIDER_STEPS}
                step={1}
                value={vsToSlider(vs)}
                onChange={(e: { currentTarget: { value: string } }) =>
                  setVs(sliderToVs(Number(e.currentTarget.value)))
                }
                aria-label="Stabilizing selection width V s"
                style={{
                  width: 220,
                  accentColor: theme.accent.primary,
                  cursor: "pointer",
                }}
              />
              <Text tone="secondary" size="small">
                {vs >= 0.01 ? vs.toFixed(3) : vs.toFixed(4)}
              </Text>
            </Row>

            <Row gap={8} wrap>
              <Stat value={zStar.toFixed(2)} label="optimum z*" />
              <Stat
                value={vs >= 0.01 ? vs.toFixed(3) : vs.toFixed(4)}
                label="width Vs"
              />
              <Stat value={sEq.toFixed(1)} label="s = 1/(2 Vs)" />
              <Stat
                value={fitnessW(0, vs, zStar).toFixed(3)}
                label="W at z = 0"
              />
              <Stat
                value={fitnessW(1, vs, zStar).toFixed(3)}
                label="W at z = 1"
              />
            </Row>

            <div
              style={{
                border: `1px solid ${theme.stroke.tertiary}`,
                background: theme.bg.editor,
                padding: "8px 4px 4px",
              }}
            >
              <FitnessProfile vs={vs} zStar={zStar} />
              <HasseDiagram n={n} colorBy="fitness" vs={vs} zStar={zStar} />
            </div>

            <Text tone="secondary" size="small">
              Same left-to-right trait axis. Fill is fitness: red = low W,
              green = high W. The dashed line is z*. Because W depends only on
              z, a whole Hamming-weight layer is one color — that is why the
              large-n picture can collapse 2ⁿ nodes to n+1 bars without losing
              the fitness landscape.
            </Text>
          </Stack>
        </CardBody>
      </Card>

      <Card>
        <CardHeader>Boltzmann η_maint — α fixed</CardHeader>
        <CardBody>
          <Stack gap={14}>
            <Text>
              {"φ_n = Dirichlet(α,…,α) on K = 2^n genotypes. α held fixed."}{" "}
              Total concentration {"α₀ = Kα = 2^n α"} then grows with n, so the
              neutral measure concentrates around equal genotype frequencies.
              Uses Vs and z* from above.
            </Text>
            <Row gap={12} align="center" wrap>
              <Text weight="medium">n</Text>
              <input
                type="range"
                min={0}
                max={SLIDER_STEPS}
                step={1}
                value={nToSlider(n)}
                onChange={(e: { currentTarget: { value: string } }) =>
                  setN(sliderToN(Number(e.currentTarget.value)))
                }
                aria-label="Number of loci for Boltzmann"
                style={{
                  width: 220,
                  accentColor: theme.accent.primary,
                  cursor: "pointer",
                }}
              />
              <Text tone="secondary" size="small">
                {n}
              </Text>
              <Row gap={4} align="center" wrap>
                {BOLTZMANN_N_JUMPS.map((v) => (
                  <Pill
                    key={`b-${v}`}
                    size="sm"
                    active={v === n}
                    onClick={() => setN(v)}
                  >
                    {v}
                  </Pill>
                ))}
              </Row>
            </Row>
            <Row gap={12} align="center" wrap>
              <Text weight="medium">N</Text>
              <input
                type="range"
                min={NPOP_MIN}
                max={NPOP_MAX}
                step={1}
                value={npop}
                onChange={(e: { currentTarget: { value: string } }) =>
                  setNpop(Number(e.currentTarget.value))
                }
                aria-label="Population size N"
                style={{
                  width: 220,
                  accentColor: theme.accent.primary,
                  cursor: "pointer",
                }}
              />
              <Text tone="secondary" size="small">
                {npop}
              </Text>
            </Row>
            <Row gap={12} align="center" wrap>
              <Text weight="medium">α</Text>
              <input
                type="range"
                min={0}
                max={ALPHA_SLIDER_STEPS}
                step={1}
                value={alphaToSlider(alpha)}
                onChange={(e: { currentTarget: { value: string } }) =>
                  setAlpha(sliderToAlpha(Number(e.currentTarget.value)))
                }
                aria-label="Dirichlet alpha"
                style={{
                  width: 220,
                  accentColor: theme.accent.primary,
                  cursor: "pointer",
                }}
              />
              <Text tone="secondary" size="small">
                {alpha.toFixed(2)}
              </Text>
            </Row>
            {boltz ? (
              <BoltzmannReadout boltz={boltz} />
            ) : (
              <Text tone="secondary">n = {n} is outside the slider range.</Text>
            )}
            <Text tone="secondary" size="small">
              Implied {"α₀ = 2^n α"} = {formatSci(a0Implied)}
              {" · μ_→g = α/(4N)"} = {(alpha / (4 * npop)).toExponential(2)}.
              Low ESS means {"W^{2N}"} is very peaked; treat η and F* as a
              sketch.
            </Text>
          </Stack>
        </CardBody>
      </Card>

      <Card>
        <CardHeader>{"Boltzmann η_maint — α₀ = Kα fixed"}</CardHeader>
        <CardBody>
          <Stack gap={14}>
            <Text>
              {"Choose n and α₀. Then α(n) = α₀ / 2^n, so Kα stays constant."}{" "}
              Same N, Vs, z* as the α-fixed table.
            </Text>
            <Row gap={12} align="center" wrap>
              <Text weight="medium">n</Text>
              <input
                type="range"
                min={0}
                max={SLIDER_STEPS}
                step={1}
                value={nToSlider(n)}
                onChange={(e: { currentTarget: { value: string } }) =>
                  setN(sliderToN(Number(e.currentTarget.value)))
                }
                aria-label="Number of loci for fixed alpha0"
                style={{
                  width: 220,
                  accentColor: theme.accent.primary,
                  cursor: "pointer",
                }}
              />
              <Text weight="medium">{n}</Text>
              <Row gap={4} align="center" wrap>
                {BOLTZMANN_N_JUMPS.map((v) => (
                  <Pill
                    key={`b0-${v}`}
                    size="sm"
                    active={v === n}
                    onClick={() => setN(v)}
                  >
                    {v}
                  </Pill>
                ))}
              </Row>
            </Row>
            <Row gap={12} align="center" wrap>
              <Text weight="medium">{"α₀"}</Text>
              <input
                type="range"
                min={0}
                max={ALPHA0_SLIDER_STEPS}
                step={1}
                value={alpha0ToSlider(alpha0)}
                onChange={(e: { currentTarget: { value: string } }) =>
                  setAlpha0(sliderToAlpha0(Number(e.currentTarget.value)))
                }
                aria-label="Total Dirichlet concentration alpha 0"
                style={{
                  width: 220,
                  accentColor: theme.accent.primary,
                  cursor: "pointer",
                }}
              />
              <Text weight="medium">{formatSci(alpha0)}</Text>
              <Row gap={4} align="center" wrap>
                {ALPHA0_JUMPS.map((v) => (
                  <Pill
                    key={`a0-${v}`}
                    size="sm"
                    active={v === alpha0}
                    onClick={() => setAlpha0(v)}
                  >
                    {v}
                  </Pill>
                ))}
                <Pill
                  size="sm"
                  active={Math.abs(alpha0 - a0Implied) / Math.max(alpha0, 1) < 0.02}
                  onClick={() =>
                    setAlpha0(
                      clampAlpha0(
                        Number.isFinite(a0Implied) ? a0Implied : ALPHA0_DEFAULT,
                      ),
                    )
                  }
                >
                  {"= 2^n α"}
                </Pill>
              </Row>
            </Row>
            <Row gap={8} wrap>
              <Stat value={String(n)} label="loci n" />
              <Stat value={formatSci(alpha0)} label="α₀ = Kα" />
              <Stat value={formatSci(aImplied)} label="α(n) = α₀/2^n" />
            </Row>
            <Row gap={12} align="center" wrap>
              <Text weight="medium">N</Text>
              <input
                type="range"
                min={NPOP_MIN}
                max={NPOP_MAX}
                step={1}
                value={npop}
                onChange={(e: { currentTarget: { value: string } }) =>
                  setNpop(Number(e.currentTarget.value))
                }
                aria-label="Population size N for fixed alpha0"
                style={{
                  width: 220,
                  accentColor: theme.accent.primary,
                  cursor: "pointer",
                }}
              />
              <Text tone="secondary" size="small">
                {npop}
              </Text>
            </Row>
            {boltz0 ? (
              <BoltzmannReadout boltz={boltz0} />
            ) : (
              <Text tone="secondary">n = {n} is outside the slider range.</Text>
            )}
            <Text tone="secondary" size="small">
              Implied {"α(n) = α₀/2^n"} = {formatSci(aImplied)}
              {" · μ_→g = α/(4N)"} = {(aImplied / (4 * npop)).toExponential(2)}.
              If the η decline with n disappears here, the α-fixed result was
              mostly the changing neutral equilibrium, not polygenicity. This
              Dirichlet is still a parent-independent mutation structure, not
              independent per-locus mutation.
            </Text>
          </Stack>
        </CardBody>
      </Card>

      <Stack gap={8}>
        <H3>Both scalings at this n</H3>
        <Table
          headers={[
            "scaling",
            "α",
            "α₀ = Kα",
            "D bits",
            "⟨C⟩_*",
            "η_maint",
            "F* nats",
            "ESS",
          ]}
          rows={[
            [
              "α fixed",
              formatSci(alpha),
              formatSci(a0Implied),
              boltz ? boltz.D.toFixed(3) : "—",
              boltz ? boltz.C.toFixed(4) : "—",
              boltz && Number.isFinite(boltz.eta) ? boltz.eta.toFixed(3) : "—",
              boltz ? boltz.F.toFixed(4) : "—",
              boltz ? boltz.ess.toFixed(1) : "—",
            ],
            [
              "α₀ fixed",
              formatSci(aImplied),
              formatSci(alpha0),
              boltz0 ? boltz0.D.toFixed(3) : "—",
              boltz0 ? boltz0.C.toFixed(4) : "—",
              boltz0 && Number.isFinite(boltz0.eta)
                ? boltz0.eta.toFixed(3)
                : "—",
              boltz0 ? boltz0.F.toFixed(4) : "—",
              boltz0 ? boltz0.ess.toFixed(1) : "—",
            ],
          ]}
          striped
        />
        <Text tone="secondary" size="small">
          Same n, N, Vs, z*. Neither scaling makes the neutrals identical —
          only the total Dirichlet concentration is matched in the second row.
        </Text>
        <Callout tone="info" title="A regime where η rises with n">
          Hold α₀ fixed and small. On even n (so a genotype sits at z*=0.5):
          α₀=4, N=50, Vs=0.0625 gives η ≈ 7.1, 9.8, 10.4, 11.7, 12.0, 15.0
          at n=4,6,8,12,16,24. D falls, ⟨C⟩ falls faster. Canvas default
          α₀=32 is near-flat. Large α₀ kills the rise: the Dirichlet is too
          concentrated for selection to reweight. Odd n dips because no type
          has z exactly 0.5.
        </Callout>
      </Stack>

      <Stack gap={8}>
        <H3>What this picture is for</H3>
        <Text>
          The top lattice is the encoding; the bottom lattice is selection
          sitting on that encoding. Same W(z) for every n, so adding loci only
          refines where genotypes fall on a fixed fitness hill. That is the
          fair comparison for “does more loci maintain the trait more cheaply?”
          The diagram is not yet an equilibrium — it is the landscape ψ* will
          live on.
        </Text>
      </Stack>

      <Callout tone="neutral" title="What this construction claims">
        If η_maint rises with n under this family, the advantage is
        polygenicity of the encoding, not a change in the trait or in how hard
        selection is on that trait. If it falls or is flat, more genes are not
        a maintenance bargain — at least not for additive stabilizing
        selection.
      </Callout>

      <Stack gap={8}>
        <H2>Pipeline (once we start computing)</H2>
        <Table
          headers={["Step", "Object"]}
          rows={[
            ["1. Landscape", "ωₙ(g) = W(zₙ(g)) on {0,1}ⁿ"],
            ["2. Neutral eq.", "φₙ — mutation + drift, no selection"],
            ["3. Selected eq.", "ψₙ* — same mutation/drift, selection on ωₙ"],
            ["4. Information", "D_KL(ψₙ* ‖ φₙ)"],
            ["5. Cost", "⟨Cₙ⟩_ψₙ* with C(x) = D_KL(x′ ‖ x)"],
            ["6. Curve", "η_maint as a function of n"],
          ]}
        />
        <Text tone="secondary" size="small">
          Exact chain for small n; haploid diffusion / Boltzmann equilibrium
          (as in epistasis_equilibria) when 2ⁿ is too large. Population size N,
          mutation u, v must themselves be scaled or held in a way we will
          decide next — they are not yet part of the “same trait” contract.
        </Text>
      </Stack>

      <Stack gap={8}>
        <H2>What is already decided vs still open</H2>
        <Grid columns={2} gap={12}>
          <Card>
            <CardHeader trailing={<Pill size="sm">decided</Pill>}>
              Locked in
            </CardHeader>
            <CardBody>
              <Stack gap={4}>
                <Text>Observable is equilibrium η_maint, not Ḋ / (N C).</Text>
                <Text>
                  Fairness = same W(z), same phenotype interval, vary n.
                </Text>
                <Text>
                  First family: additive z = mean(g), stabilizing Gaussian W.
                </Text>
              </Stack>
            </CardBody>
          </Card>
          <Card>
            <CardHeader trailing={<Pill size="sm">next</Pill>}>
              To decide with you
            </CardHeader>
            <CardBody>
              <Stack gap={4}>
                <Text>
                  How N, u, v, recombination scale with n (or stay fixed).
                </Text>
                <Text>Other W: directional, threshold, exponential.</Text>
                <Text>
                  Other encodings: unequal effects, a few large-effect loci.
                </Text>
                <Text>Exact chain vs diffusion for n ≳ 4–6.</Text>
              </Stack>
            </CardBody>
          </Card>
        </Grid>
      </Stack>

      <Divider />

      <Text tone="tertiary" size="small">
        Polygenic Efficiency · working sketch from the proposal definition of
        maintenance efficiency and the additive-trait scaling. No numbers yet —
        this canvas is the plan, not a result.
      </Text>
    </Stack>
  );
}
